t.script:
(function () {
  var searchTimeout = null;

  // --- LOGIC CHIP SEARCH (GIỮ NGUYÊN) ---
  function initChipInput() {
      var $realInput = $('#real-search-q');
      var $container = $('#chip-container');
      var $visualInput = $('#visual-search-input');
      var currentChips = [];

      var initialVal = $realInput.val();
      if(initialVal) {
          currentChips = initialVal.split(',').map(function(s){ return s.trim(); }).filter(function(s){ return s; });
          renderChips();
      }

      function renderChips() {
          $container.find('.search-chip').remove();
          currentChips.forEach(function(term, index) {
              var $chip = $(
                  '<div class="search-chip">' +
                      '<span>' + $('<div>').text(term).html() + '</span>' +
                      '<span class="btn-close-chip" data-index="' + index + '">&times;</span>' +
                  '</div>'
              );
              $visualInput.before($chip);
          });
          updateRealInput();
      }

      function updateRealInput() {
          $realInput.val(currentChips.join(', '));
      }

      window.addSearchChip = function(term) {
          term = term.trim().replace(/,/g, '');
          if(term && !currentChips.includes(term)) {
              currentChips.push(term);
              renderChips();
          }
          $visualInput.val('');
          $visualInput.focus();
      }

      $container.on('click', '.btn-close-chip', function() {
          var idx = $(this).data('index');
          currentChips.splice(idx, 1);
          renderChips();
          $visualInput.focus();
      });

      $visualInput.on('keydown', function(e) {
          var val = $(this).val();
          if(e.key === 'Backspace' && val === '' && currentChips.length > 0) {
              currentChips.pop();
              renderChips();
          } else if (e.key === 'Enter') {
              e.preventDefault();
              if (val.trim()) {
                  addSearchChip(val);
                  $('#search-form').submit();
              } else {
                  $('#search-form').submit();
              }
          } else if (e.key === ',') {
              e.preventDefault();
              if (val.trim()) {
                  addSearchChip(val);
              }
          }
      });

      $container.on('click', function(e) {
          if(e.target === this) $visualInput.focus();
      });
  }

  // --- LOGIC GỢI Ý (GIỮ NGUYÊN) ---
  function debounce(func, wait) {
    return function() {
      var context = this, args = arguments;
      clearTimeout(searchTimeout);
      searchTimeout = setTimeout(function() { func.apply(context, args); }, wait);
    };
  }

  function searchProducts(term, callback) {
    $.ajax({
      url: "/search_stock/suggest",
      type: "POST", dataType: "json", contentType: "application/json",
      data: JSON.stringify({ jsonrpc: "2.0", method: "call", params: { q: term }, id: new Date().getTime() }),
      success: function(resp) {
        var result = (resp && resp.result) ? resp.result : {};
        callback(result.products || []);
      }
    });
  }

  function renderSuggestions(products) {
    var $dropdown = $('#search-suggestions');
    if (!products || products.length === 0) {
      $dropdown.hide().empty();
      return;
    }
    var html = '';
    products.forEach(function(p) {
       var displayName = p.name || p.default_code || '';
       html += '<div class="suggestion-item border-bottom p-2" data-name="' + displayName + '" style="cursor:pointer;">';
       html += '  <div class="d-flex align-items-center">';
       if (p.image_url) {
           html += '<img src="' + p.image_url + '" class="rounded border me-2 flex-shrink-0" style="width:40px; height:40px; object-fit:cover;"/>';
       } else {
           html += '<div class="rounded border me-2 bg-light d-flex align-items-center justify-content-center flex-shrink-0" style="width:40px; height:40px;"><i class="fa fa-cube text-muted"></i></div>';
       }
       html += '    <div class="flex-grow-1 overflow-hidden">';
       html += '      <div class="fw-bold text-dark text-truncate" style="font-size:0.9rem;">' + (p.default_code || '') + '</div>';
       html += '      <div class="text-muted text-truncate small">' + (p.name || '') + '</div>';
       html += '    </div>';
       html += '    <div class="ms-2 text-primary"><i class="fa fa-angle-right"></i></div>';
       html += '  </div>';
       html += '</div>';
    });
    $dropdown.html(html).show();
  }

  $(document).ready(function() {
    initChipInput(); 

    var $visualInput = $('#visual-search-input');
    var $dropdown = $('#search-suggestions');

    $visualInput.on('input', debounce(function() {
      var term = $(this).val().trim();
      if (term.length >= 2) {
        searchProducts(term, renderSuggestions);
      } else {
        $dropdown.hide();
      }
    }, 300));

    $(document).on('click', '.suggestion-item', function() {
      var name = $(this).data('name');
      if (name) {
        window.addSearchChip(name);
        $dropdown.hide();
        $('#search-form').submit();
      }
    });

    $(document).on('click', function(e) {
      if (!$(e.target).closest('#chip-container, #search-suggestions').length) {
        $dropdown.hide();
      }
    });

    // --- LOGIC EXPAND ---
    $(document).on('click', '.btn-expand', function () {
       var $btn = $(this);
       var pid = $btn.data('pid');
       var isCombo = String($btn.data('is-combo')) === 'true';
       var $row = $btn.closest('tr');
       var $next = $row.next();

       if ($next.length && $next.hasClass('detail-row') && $next.is(':visible')) {
         $next.remove();
         $btn.html('<i class="fa fa-plus"></i>');
         return;
       }

       var colCount = $row.children('td').length;
       var $detail = $('<tr class="detail-row bg-white"><td colspan="' + colCount + '" class="p-3 shadow-inset" style="background-color:#f8f9fa;"><div class="d-flex align-items-center"><span class="spinner-border spinner-border-sm me-2"></span>Đang tải dữ liệu...</div></td></tr>');
       $row.after($detail);
       $btn.html('<i class="fa fa-minus"></i>');

       var currentWid = $('select[name="warehouse_id"]').val() || '';
       var detailMode = isCombo ? 'per_warehouse' : null;

       $.ajax({
          url: "/search_stock/product_breakdown",
          type: "POST", dataType: "json", contentType: "application/json",
          data: JSON.stringify({jsonrpc: "2.0", method: "call", params: { product_id: pid, warehouse_id: currentWid, detail_mode: detailMode }, id: 1}),
          success: function(resp) {
              var res = (resp && resp.result) ? resp.result : {};
              if(res.ok) {
                 $detail.find('td').html(buildDetailTable(res));
              } else {
                 $detail.find('td').html('<div class="text-danger small">Lỗi: ' + (res.error || 'Unknown') + '</div>');
              }
          }
       });
    });
  });

  // --- HELPER RENDER BẢNG CHI TIẾT ĐẸP HƠN ---
  function fmt(n) { return (parseFloat(n)||0).toLocaleString('en-US'); }

  function buildDetailTable(data) {
      var html = '';
      var rows = data.rows || [];

      // TRƯỜNG HỢP 1: COMBO PRODUCT (Hiển thị dạng Card từng item con)
      if(data.mode === 'components_by_warehouse') {
          html += '<div class="row g-3">'; // Sử dụng grid row của bootstrap
          rows.forEach(function(c){
              html += '<div class="col-12 col-md-12">'; // Mỗi sản phẩm con là 1 block
              html += '  <div class="card h-100 border shadow-sm">';

              // Header: Ảnh + Tên + SL cần
              html += '    <div class="card-header bg-white d-flex align-items-center py-2">';
              if(c.image_url) {
                  html += '      <img src="' + c.image_url + '" class="rounded border me-3" style="width:48px; height:48px; object-fit:contain;">';
              } else {
                  html += '      <div class="rounded border me-3 d-flex align-items-center justify-content-center bg-light text-muted" style="width:48px; height:48px;"><i class="fa fa-cube"></i></div>';
              }
              html += '      <div class="flex-grow-1">';
              html += '        <div class="fw-bold text-primary">' + c.name + '</div>';
              html += '        <div class="small text-muted">Mã: ' + c.default_code + ' | ĐVT: ' + c.uom + '</div>';
              html += '      </div>';
              html += '      <div class="text-end border-start ps-3">';
              html += '        <div class="small text-muted">Cần cho 1 Combo</div>';
              html += '        <div class="fw-bold fs-5 text-dark">' + fmt(c.component_qty_in_combo) + '</div>';
              html += '      </div>';
              html += '    </div>'; // End Header

              // Body: Table Tồn kho
              html += '    <div class="card-body p-0">';
              html += '      <table class="table table-sm table-striped mb-0">';
              html += '        <thead class="bg-light text-muted small">';
              html += '          <tr>';
              html += '            <th class="ps-3 border-0">Kho hàng</th>';
              html += '            <th class="text-end border-0">Tồn thực tế</th>';
              html += '            <th class="text-end border-0">Đã giữ</th>';
              html += '            <th class="text-end border-0 pe-3">Khả dụng</th>';
              html += '          </tr>';
              html += '        </thead>';
              html += '        <tbody>';

              (c.warehouses||[]).forEach(function(w){
                  // Highlight nếu có hàng khả dụng
                  var availClass = (w.qty_available > 0) ? 'text-success fw-bold' : 'text-muted';

                  html += '          <tr>';
                  html += '            <td class="ps-3">' + w.warehouse_name + '</td>';
                  html += '            <td class="text-end">' + fmt(w.qty_total) + '</td>';
                  html += '            <td class="text-end text-muted">' + fmt(w.qty_reserved) + '</td>';
                  html += '            <td class="text-end pe-3 ' + availClass + '">' + fmt(w.qty_available) + '</td>';
                  html += '          </tr>';
              });

              html += '        </tbody>';
              html += '      </table>';
              html += '    </div>'; // End Body
              html += '  </div>'; // End Card
              html += '</div>'; // End Col
          });
          html += '</div>'; // End Row
      } 

      // TRƯỜNG HỢP 2: SẢN PHẨM THƯỜNG (Table đơn giản)
      else {
          html += '<div class="card border shadow-sm" style="max-width: 800px;">';
          html += '  <table class="table table-hover mb-0">';
          html += '    <thead class="bg-light text-muted"><tr><th class="ps-3">Kho hàng</th><th class="text-end">Tồn thực tế</th><th class="text-end">Đã giữ</th><th class="text-end pe-3">Khả dụng</th></tr></thead>';
          html += '    <tbody>';
          rows.forEach(function(r){
              var availClass = (r.qty_available > 0) ? 'text-success fw-bold' : 'text-muted';
              html += '      <tr>';
              html += '        <td class="ps-3">' + r.warehouse_name + '</td>';
              html += '        <td class="text-end">' + fmt(r.qty_total) + '</td>';
              html += '        <td class="text-end text-muted">' + fmt(r.qty_reserved) + '</td>';
              html += '        <td class="text-end pe-3 ' + availClass + '">' + fmt(r.qty_available) + '</td>';
              html += '      </tr>';
          });
          html += '    </tbody></table></div>';
      }

      return html;
  }

})();
